from lesson_helpers import *
from lesson_figures import figure,CSS
T=['Définition','Épidémiologie','Physiopathologie','Démarche clinique','Anamnèse','Examen clinique','Syndromes','Diagnostic positif','Explorations','Arbre diagnostique et diagnostics différentiels','Prise en charge','Prévention, suivi et pronostic','Points clés','Pièges']
a='''<template id="ch-D77"><div class="chap"><div class="chap-head"><div class="code">D77* · H-08-Hématologie · CIM-10-GM suisse 2024</div><h1>Autres maladies du sang et des organes hématopoïétiques au cours de maladies classées ailleurs</h1><p>Monographie clinique : fibrose splénique et hypersplénisme de la schistosomiase hépatosplénique.</p><span class="status">Sol-Hématologie-D77 · Auto-relecture IA documentée · Sans validation médicale humaine</span></div><div class="tabs ui" role="tablist"><button role="tab" aria-controls="pA" data-p="pA" aria-selected="true">⚕ Pathologie et prise en charge</button><button role="tab" aria-controls="pE" data-p="pE" aria-selected="false">🔬 Examens complémentaires</button><button role="tab" aria-controls="pS" data-p="pS" aria-selected="false">⚛ Sciences fondamentales spécialisées</button><button role="tab" aria-controls="pP" data-p="pP" aria-selected="false">💊 Pharmacologie</button></div>'''+CSS+'''<div class="panel" id="pA"><nav class="toc ui"><b>Plan monographique</b><ol>'''+''.join('<li><a href="#d77-'+str(i)+'">'+t+'</a></li>' for i,t in enumerate(T,1))+'''</ol></nav><div class="chap-body" data-semiology-clinical="D77">'''
a+=sec('question','Une grosse rate et des plaquettes basses : où se trouve le problème ?', '''<p><b>Vignette fictive.</b> Une personne ayant vécu en zone d’endémie rapporte des baignades en eau douce. Une splénomégalie et une thrombocytopénie ont été découvertes ; elle mentionne aussi un épisode de vomissement sanglant. Les transaminases peu perturbées suffisent-elles à rassurer ? Faut-il enlever la rate pour corriger la numération ?</p><p>La priorité est le saignement possible, puis l’explication de l’association entre exposition, maladie parasitaire, circulation portale et signes sanguins. Un foie encore fonctionnel peut être traversé par une hypertension portale importante. Une faible numération ne prouve pas à elle seule un défaut médullaire, et une rate volumineuse ne prouve pas une schistosomiase.</p>'''+key('Évaluer la gravité avant d’attribuer une cytopénie à la rate.'),('EU-CLIN','INT-HSS-MEC','INT-HSS-DX'))
a+=sec(1,'1. Définition : manifestation, syndrome et cause', '''<p>D77* est une catégorie de manifestation : « Autres maladies du sang et des organes hématopoïétiques au cours de maladies classées ailleurs ». Son inclusion explicite dans la CIM-10-GM suisse 2024 est la <b>fibrose splénique due à la schistosomiase [bilharziose] (B65.-†)</b>. D77 n’a pas de sous-code décimal dans cette version. Le code de la maladie causale et celui de sa manifestation ne remplacent pas la démonstration clinique.</p><p>Cette monographie développe cette inclusion, sans prétendre que toute maladie classable en D77 soit une bilharziose. La <b>splénomégalie</b> décrit une augmentation de volume ; l’<b>hypersplénisme</b> décrit un retentissement hématologique associé à la rate ; la <b>fibrose</b> décrit une transformation tissulaire. Ces termes ne sont pas interchangeables. Une grande rate n’est pas automatiquement une rate non fonctionnelle.</p><p>La schistosomiase hépatosplénique associe notamment fibrose périportale, hypertension portale présinusoïdale et splénomégalie. Le caractère « splénique » du libellé de classification ne doit pas faire oublier le mécanisme portal et la recherche de la cause parasitaire.</p>''',('CH-CIM','INT-HSS-MEC','CH-CHUV-ASPLEN'))
a+=sec(2,'2. Épidémiologie : exposition et sélection des populations', '''<p>L’exposition pertinente est un contact cutané avec de l’eau douce contaminée dans une région d’endémie : lieu de naissance, séjour, migration, activité professionnelle ou voyage. L’infection peut persister et les symptômes chroniques être discrets. Une brève exposition ne garantit pas l’absence d’infection ; l’absence d’éosinophilie ne suffit pas à l’écarter.</p><p>Les formes hépatospléniques sont surtout associées à <i>S. mansoni</i> et <i>S. japonicum</i>. <i>S. haematobium</i> oriente davantage vers une atteinte urogénitale. Cette orientation ne remplace pas l’identification ni l’étude d’une atteinte concomitante. Une hématurie terminale dans un récit d’exposition doit être explorée, sans la prendre pour une preuve d’hypertension portale.</p><p>Aucune incidence suisse spécifique de D77 ni fréquence universelle de cytopénie n’est retenue dans les documents lus. Les cohortes de formes compliquées et les séries d’intervention sélectionnent des personnes malades ; leurs proportions ne représentent pas tous les migrants, tous les voyageurs ou toutes les infections.</p>''',('EU-CLIN','CH-RMS-DX','INT-HSS-LIMIT'))
a+=sec(3,'3. Physiopathologie : œufs, tissu et circulation', '''<p>Les cercaires pénètrent la peau au contact de l’eau contaminée. Le cycle conduit à des vers adultes et à une production d’œufs ; une partie des œufs se retrouve dans les tissus. La réaction inflammatoire granulomateuse aux œufs contribue à la fibrose périportale. Il ne s’agit pas simplement d’un ver qui bouche directement la veine porte.</p>'''+figure('egg')+'''<p>L’augmentation de résistance en amont des sinusoïdes explique une hypertension portale <b>présinusoïdale</b>. La congestion et l’augmentation du flux splénique contribuent à la splénomégalie ; des voies collatérales et des varices peuvent se développer. La fonction hépatocellulaire est souvent relativement préservée, ce qui distingue ce mécanisme d’une cirrhose avancée, sans garantir un foie toujours indemne.</p>'''+figure('portal')+'''<p>Thrombocytopénie et leucopénie peuvent accompagner ce tableau. La revue HSS 2021 souligne l’incertitude entre stase intrasplénique, séquestration et destruction ; il serait excessif de présenter toute baisse de numération comme une destruction immune démontrée. L’anémie peut aussi résulter de pertes digestives, de carences ou d’autres maladies. Plusieurs mécanismes peuvent coexister.</p><p>Le praziquantel traite l’infection sensible ; la régression de certaines lésions ou de l’hypertension portale peut survenir, surtout tôt et chez les jeunes. Les lésions avancées peuvent persister. Dire que la fibrose ne régresse jamais serait aussi trompeur que promettre sa disparition après une dose.</p>''',('EU-CLIN','INT-HSS-MEC','INT-HSS-TX','INT-HSS-LIMIT'))
a+=sec(4,'4. Démarche clinique : gravité, cause puis retentissement', '''<p><b>Première étape : rechercher une urgence.</b> Hématémèse, méléna, malaise, altération de conscience ou signes circulatoires imposent une évaluation et une prise en charge urgentes. Une hémorragie peut être grave avec une fonction hépatique jusque-là conservée. Sous bêtabloquant, l’absence de tachycardie ne rassure pas à elle seule.</p><p><b>Deuxième étape : établir la plausibilité causale.</b> Documenter les expositions et les traitements antérieurs, puis choisir les examens parasitologiques selon l’espèce et le site suspectés. La sérologie complète l’enquête mais ne sépare pas de façon fiable infection ancienne et infection active.</p><p><b>Troisième étape : décrire les organes et le sang.</b> Numération, frottis selon le contexte, bilan hépatique, échographie-Doppler et évaluation des varices répondent à des questions distinctes. Une numération n’imagine pas la veine porte et une échographie ne prouve pas la présence d’un œuf viable.</p><p><b>Quatrième étape : organiser les soins.</b> Avis de médecine tropicale/infectiologie et hépatologie, avec hématologie lorsque le profil sanguin est discordant ou complexe. Le traitement de l’infection et la prévention d’une hémorragie portale ne sont pas une seule intervention.</p>''',('EU-DX','INT-HSS-DX','FI-PROPRANOLOL','EU-TX'))
a+=sec(5,'5. Anamnèse : relier chronologie et mécanismes', '''<p>Préciser pays et dates de résidence ou de séjour, type d’eau, baignades et activités, épisodes de fièvre après exposition, diagnostics antérieurs, praziquantel reçu et éventuelles réexpositions. La forme aiguë peut associer fièvre, rash, toux ou dyspnée dans les semaines après l’exposition ; elle ne se gère pas comme une simple infection chronique stable.</p><p>Rechercher saignements digestifs et leur calendrier, fatigue, dyspnée, pesanteur de l’hypocondre gauche et augmentation du volume abdominal. Documenter diarrhée, sang dans les selles, hématurie terminale, symptômes urinaires et signes neurologiques. Une plainte oriente un compartiment ; elle ne suffit pas à identifier le mécanisme.</p><p>Recueillir antécédents hépatiques, autres infections, alcool, médicaments, grossesse, allaitement et traitements qui modifient les numérations ou la pression. Une rifampicine prescrite ailleurs est une donnée essentielle avant praziquantel. Demander si la personne a déjà subi une splénectomie ou reçu un plan de prévention d’asplénie ; cela change la conduite devant une fièvre.</p>''',('EU-CLIN','CH-RMS-DX','EU-PRAZI-RCP','CH-CHUV-FEVER'))
a+=sec(6,'6. Examen clinique : volume, saignement et état général', '''<p>Commencer par l’état général, la conscience, la pression, le pouls, la perfusion et les signes de saignement. La recherche d’une grosse rate vient après la sécurité immédiate. Décrire pâleur, lésions cutanées hémorragiques éventuelles, ictère, abdomen distendu et signes respiratoires ; aucun de ces signes isolés n’est spécifique de la bilharziose.</p><p>Palper prudemment le foie et la rate, décrire douleur, limites et consistance, rechercher ascite et circulation collatérale. L’examen clinique situe le problème mais l’échographie fournit une mesure et étudie les vaisseaux. Une rate non palpée n’exclut pas toute anomalie ; une rate palpable ne prouve pas une fibrose.</p>'''+figure('spleen')+'''<p>La conservation de la fonction hépatique et l’absence d’ascite peuvent coexister avec des varices à risque. Inversement, une ascite, un ictère ou une altération de synthèse imposent de rechercher une forme avancée ou une autre atteinte associée. Chez l’enfant, les formes portales peuvent se présenter sans image périportale typique : le modèle adulte ne doit pas être appliqué mécaniquement.</p>''',('INT-HSS-MEC','INT-HSS-DX','INT-HSS-LIMIT'))
a+=sec(7,'7. Syndromes : séparer ce qui peut coexister',table(['Profil','Ce qu’il suggère','Ce qu’il ne prouve pas'],[
['Splénomégalie + thrombocytopénie/leucopénie','Retentissement splénique possible dans un contexte portal','Ni cause parasitaire certaine, ni mécanisme exclusif de destruction'],
['Splénomégalie + varices/collatérales','Hypertension portale à caractériser','Cirrhose obligatoire ou fonction hépatique nécessairement effondrée'],
['Anémie + saignement digestif','Perte sanguine et retentissement à évaluer','Anémie uniquement due à l’hypersplénisme'],
['Fièvre après exposition, rash/toux/dyspnée','Forme aiguë possible, avis spécialisé','Forme chronique stable justifiant un traitement automatique sans bilan'],
['Fièvre après splénectomie ou asplénie fonctionnelle documentée','Risque infectieux urgent','Situation équivalente à toute simple splénomégalie']])+'''<p>Ces profils sont des regroupements cliniques. Ils guident les investigations et l’urgence ; ils ne constituent pas des critères chiffrés validés pour attribuer D77. Une cytopénie profonde ou atypique doit faire rechercher d’autres mécanismes plutôt que de refermer le dossier sur la rate.</p>''',('INT-HSS-MEC','EU-CLIN','CH-CHUV-FEVER'))
a+=sec(8,'8. Diagnostic positif : croiser des preuves différentes', '''<p>La preuve de schistosomiase repose notamment sur la mise en évidence d’œufs dans les selles, les urines ou un tissu selon la situation. La sensibilité d’un prélèvement peut être faible ; une négativité n’éteint pas une forte suspicion. Les examens répétés, la sérologie et les techniques spécialisées sont choisis avec le laboratoire et le spécialiste.</p><p>La sérologie est utile dans l’enquête d’exposition et le dépistage ciblé, mais peut rester positive longtemps. Elle ne suffit pas à démontrer une infection active, la guérison ou une fibrose splénique. Une image d’œuf publiée pour apprendre sa morphologie n’est pas un résultat du patient.</p><p>Le diagnostic de forme hépatosplénique ajoute les données hépatoportales et spléniques : échographie-Doppler, contexte clinique, complications et examens appropriés. L’endoscopie établit la présence et le grade des varices. Les rapports plaquettes/taille splénique étudiés dans de petites séries ne sont pas des règles universelles permettant d’exclure des varices.</p><p>Le choix D77* n’intervient qu’après documentation de la manifestation et de la maladie causale B65.-†. Une thrombocytopénie isolée avec une sérologie ancienne positive n’est pas une démonstration suffisante.</p>''',('EU-DX','CH-RMS-DX','INT-HSS-DX','CH-CIM'))
a+=sec(9,'9. Explorations : une question par examen',table(['Examen','Question','Limite ou suite'],[
['Numération et évolution, frottis si indiqué','Quelles lignées, quelle profondeur et quelle trajectoire ?','Interpréter avec références du laboratoire et contexte ; la numération ne prouve pas le mécanisme'],
['Bilan hépatique et de synthèse adapté','Fonction préservée, atteinte associée ou décompensation ?','Des enzymes peu perturbées n’excluent pas une hypertension portale'],
['Recherche d’œufs, sérologie, tests spécialisés selon le site','Infection plausible, documentée, active ou ancienne ?','Expliquer la sensibilité, la persistance sérologique et les limites de disponibilité'],
['Échographie-Doppler','Fibrose périportale, taille des organes, flux, collatérales ou thrombose ?','N’établit pas seule l’activité parasitaire ; critères pédiatriques et expertise comptent'],
['Endoscopie digestive','Varices et risque hémorragique à évaluer ?','Ne pas remplacer par une règle plaquettes/rate non validée universellement'],
['Exploration tissulaire ou médullaire sélectionnée','Une autre maladie changerait-elle la prise en charge ?','Pas de biopsie splénique ou médullaire automatique sur une cytopénie attribuée sans enquête']])+'''<p>Le choix dépend de l’urgence et de ce qui modifiera le plan. Chez une personne instable ou qui saigne, la séquence de soins ne peut pas attendre un dossier parasitologique complet.</p>''',('CH-HUG-LAB','EU-DX','INT-HSS-DX','INT-HSS-LIMIT'))
a+=sec(10,'10. Arbre diagnostique et diagnostics différentiels', '''<ol><li><b>Saignement ou instabilité ?</b> Prise en charge urgente, puis recherche et traitement de la source avec l’équipe adaptée.</li><li><b>Splénomégalie et numération anormale confirmées ?</b> Comparer aux résultats antérieurs et au frottis lorsque pertinent ; rechercher mécanismes associés.</li><li><b>Exposition compatible ?</b> Enquête parasitologique ciblée ; ne pas confondre sérologie ancienne et maladie active.</li><li><b>Hypertension portale présente ?</b> Imagerie vasculaire et évaluation des varices, en distinguant obstacle, fibrose périportale et autres maladies du foie.</li><li><b>Concordance complète ?</b> Documenter cause et manifestation ; sinon élargir l’enquête et demander les avis pertinents.</li></ol><p>Les autres causes de splénomégalie et de cytopénies comprennent infections, maladies hématologiques, troubles de production ou de destruction et autres maladies hépatoportales. Une perte digestive ou une carence peut contribuer à l’anémie. Il faut rechercher une cause coexistante lorsque les résultats ne sont pas expliqués par le mécanisme retenu.</p><p>L’EASL 2026 exclut explicitement la schistosomiase de la définition de la maladie vasculaire porto-sinusoïdale (PSVD). « Hypertension portale sans cirrhose » n’est donc pas automatiquement « PSVD ». Les seuils et stratégies conçus pour cirrhose ou PSVD ne deviennent pas des règles HSS par simple analogie.</p>''',('EU-DX','INT-HSS-DX','INT-HSS-LIMIT','EU-EASL-BOUND'))
a+=sec(11,'11. Prise en charge : traiter la cause et les complications', '''<p><b>Urgence hémorragique.</b> Une hématémèse ou un méléna avec retentissement nécessite une filière urgente et une évaluation endoscopique appropriée. Le traitement oral du parasite ou l’augmentation d’un bêtabloquant à domicile ne remplace pas cette prise en charge. Une forme aiguë sévère ou neurologique relève également d’un avis spécialisé.</p><p><b>Infection.</b> Le praziquantel est le traitement de référence dans les sources consultées, avec schéma adapté à l’espèce, au produit et à la personne. La liste Swissmedic du 30 septembre 2026 et les recherches AmiKo n’ont pas fourni d’entrée praziquantel/Biltricide : c’est une constatation datée, sans preuve d’indisponibilité définitive. Le pharmacien et le spécialiste vérifient le produit réellement accessible et, si nécessaire, les conditions légales d’importation. Le RCP français décrit les doses, sans devenir une FI suisse.</p><p><b>Hypertension portale.</b> La prévention d’hémorragie et les traitements endoscopiques sont discutés avec l’hépatologue. Le propranolol dispose d’une indication suisse concernant la prévention des hémorragies digestives hautes avec hypertension portale et varices, hors cirrhose décompensée selon la FI. Le carvédilol suisse consulté n’a pas cette indication ; une préférence issue de la cirrhose ne s’impose pas automatiquement à la HSS.</p><p><b>Interventions.</b> Chirurgie, dérivations ou TIPS peuvent être discutés dans des situations sélectionnées. Les preuves HSS restent hétérogènes et les comparaisons limitées. Une splénectomie n’est pas la réponse automatique à une numération basse ; elle crée notamment des obligations de prévention infectieuse. Les décisions prennent en compte saignements, circulation, fonction, autres maladies et ressources de suivi.</p>''',('EU-TX','CH-PRAZI-STATUS','CH-IMPORT','EU-PRAZI-RCP','FI-PROPRANOLOL','FI-CARVEDILOL','INT-HSS-TX','CH-CHUV-ASPLEN'))
a+=sec(12,'12. Prévention, suivi et pronostic : un plan à plusieurs horizons', '''<p>Prévenir les nouvelles expositions à l’eau douce contaminée et expliquer que le traitement ne procure pas une immunité contre une réinfection. Organiser le suivi parasitologique et clinique ; le consensus espagnol propose une réévaluation globale vers trois mois, avec modalités adaptées. Une complication impose un contrôle plus tôt, et une sérologie persistante n’est pas à elle seule une indication de retraitement.</p><p>Suivre numérations, symptômes, état hépatoportal et varices selon le plan spécialisé. Une guérison parasitologique ne signifie pas disparition immédiate des collatérales ou d’une fibrose avancée. À l’inverse, certaines lésions peuvent régresser : le pronostic dépend de l’ancienneté, des complications, des réexpositions et des maladies associées.</p><p>Si splénectomie prévue ou asplénie fonctionnelle documentée, prévoir information, vaccinations et plan antibiotique individuel. Le protocole CHUV révisé le 9 septembre 2024 conseille d’anticiper si possible les vaccinations avant une chirurgie élective ; le calendrier et les produits doivent être vérifiés dans les recommandations suisses en vigueur. Une simple splénomégalie ne suffit pas à appliquer le statut d’asplénie.</p><p>Après splénectomie, fièvre, état grippal ou morsure justifient un contact urgent. Le CHUV insiste sur l’absence d’attente nocturne ; si un avis n’est pas accessible rapidement, la réserve antibiotique prescrite dans le plan individuel doit être utilisée selon ce plan, puis l’évaluation poursuivie. Ce cours ne fabrique pas une posologie antibiotique sans FI du produit prescrit.</p>''',('EU-FOLLOW','INT-HSS-TX','CH-CHUV-ASPLEN','CH-CHUV-FEVER'))
a+=sec(13,'13. Points clés : ce qui change une décision', '''<ul><li>Une cytopénie et une grande rate appellent une explication ; elles ne constituent pas un diagnostic causal.</li><li>La HSS peut provoquer des varices graves avec une fonction hépatique relativement préservée.</li><li>Les œufs et la réaction tissulaire expliquent la fibrose ; l’imagerie et l’endoscopie décrivent un autre niveau de preuve.</li><li>Une sérologie positive ne suffit pas à démontrer activité, guérison ou fibrose.</li><li>Traiter l’infection n’annule pas le suivi des complications portales.</li><li>Le produit réellement disponible, sa FI/RCP et la population déterminent la prescription.</li><li>D77* décrit une manifestation à relier à la maladie causale ; aucun sous-code D77.x n’est inventé.</li></ul>''',('CH-CIM','EU-DX','INT-HSS-MEC','EU-TX','EU-PRAZI-RCP'))
a+=sec(14,'14. Pièges : raccourcis qui exposent à une erreur', '''<p>Rassurer sur les seules transaminases, attribuer toute anémie à l’hypersplénisme, déduire une guérison de l’absence d’éosinophilie, ou appeler cirrhose toute hypertension portale effacent des mécanismes importants. Un dosage sérologique et une photographie histologique normale ne démontrent pas une infection active ni une fibrose chez la personne examinée.</p><p>Les autres raccourcis à éviter sont la splénectomie motivée uniquement par un chiffre, la transposition d’un traitement de cirrhose sans justification HSS, l’application à l’enfant d’un schéma adulte et la présentation d’un RCP étranger comme FI suisse. La recommandation OMS en santé publique et le RCP d’un produit peuvent différer pour grossesse, allaitement ou âge : la différence doit être attribuée et résolue pour le produit réel.</p>'''+trap('Ne pas transformer une incertitude de source ou de disponibilité en certitude clinique.'),('INT-HSS-LIMIT','EU-EASL-BOUND','INT-WHO','EU-PRAZI-RCP'))
a+='</div></div>';save('a',a)
print('D77 : quatorze points monographiques écrits, marqueur clinique sur prose réelle.')
